-- =============================================
-- Recenzje (w skali 1–5) – każdy film ma min. 2 oceny
-- =============================================
INSERT INTO Review (movie_id, account_id, rating, title, content) VALUES
-- ====== Podstawowa siatka: każdy użytkownik ocenia kilka filmów ======
-- ShadowCoder (filmy 1, 6, 11)
(1, (SELECT id FROM Account WHERE username = 'ShadowCoder'), 5, 'Kod umysłu', 'Warstwy snów jak zagnieżdżone pętle – genialne. Zimmer daje tu popis.'),
(6, (SELECT id FROM Account WHERE username = 'ShadowCoder'), 5, 'Rycerz chaosu', 'Joker to najlepszy czarny charakter dekady. Film mroczny i bezkompromisowy.'),
(11, (SELECT id FROM Account WHERE username = 'ShadowCoder'), 4, 'Grawitacja uczuć', 'Interstellar wzrusza bardziej niż niejeden dramat. Sceny z Cooperem i Murph łamią serce.'),

-- NightOwl (filmy 2, 7, 12)
(2, (SELECT id FROM Account WHERE username = 'NightOwl'), 5, 'Neo się kłania', 'Matrix wciąż jest świeży. Sekwencje walk i zielony kod są ikoniczne.'),
(7, (SELECT id FROM Account WHERE username = 'NightOwl'), 5, 'Wyprawa po nadzieję', 'Fellowship to czysta magia. Każdy członek drużyny ma serce.'),
(12, (SELECT id FROM Account WHERE username = 'NightOwl'), 5, 'Nadzieja w murach', 'Shawshank udowadnia, że cierpliwość i spryt potrafią pokonać system.'),

-- PixelQueen (filmy 3, 8, 13)
(3, (SELECT id FROM Account WHERE username = 'PixelQueen'), 4, 'Biznes rodzinny', 'Corleone to mistrzostwo narracji. Oglądam głównie dla Michaela.'),
(8, (SELECT id FROM Account WHERE username = 'PixelQueen'), 5, 'Skrzynka z dialogami', 'Pulp Fiction to scenariusz idealny – każdy fragment błyszczy.'),
(13, (SELECT id FROM Account WHERE username = 'PixelQueen'), 5, 'Rohan w ogniu', 'Dwie Wieże podkręcają akcję. Bitwa pod Helmowym Jarem to audiowizualny majstersztyk.'),

-- RetroGamer (filmy 4, 9, 14)
(4, (SELECT id FROM Account WHERE username = 'RetroGamer'), 3, 'Powrót do Matriksa', 'Reaktywacja cierpi przez nadmiar ekspozycji, ale scena na autostradzie wymiata.'),
(9, (SELECT id FROM Account WHERE username = 'RetroGamer'), 2, 'Król na ekranie', 'Michael zapowiada się dobrze, ale ciężko oceniać przedpremierowo. Mam mieszane uczucia.'),
(14, (SELECT id FROM Account WHERE username = 'RetroGamer'), 5, 'Schody i deszcz', 'Parasite to perfekcyjna metafora klas. Finał w piwnicy mrozi krew.'),

-- WaveRider (filmy 5, 10, 15)
(5, (SELECT id FROM Account WHERE username = 'WaveRider'), 4, 'Ostatni lot Logosa', 'Rewolucje zamykają sagę z hukiem. Bitwa o Syjon to czysta adrenalina.'),
(10, (SELECT id FROM Account WHERE username = 'WaveRider'), 4, 'Cyrk w finale', 'Digital Circus na dużym ekranie daje radę. Animacja robi wrażenie.'),
(15, (SELECT id FROM Account WHERE username = 'WaveRider'), 5, 'Tempo i krew', 'Whiplash trzyma w napięciu jak thriller. Simmons jest przerażający.'),

-- StarSeeker (filmy 1, 4, 7) – drugi głos przy filmach 1, 4, 7
(1, (SELECT id FROM Account WHERE username = 'StarSeeker'), 4, 'Nolan w formie', 'Incepcja to labirynt, z którego nie chcę wychodzić.'),
(4, (SELECT id FROM Account WHERE username = 'StarSeeker'), 3, 'Ciąg dalszy podróży', 'Więcej Matrixa zawsze na propsie, choć tempo spada.'),
(7, (SELECT id FROM Account WHERE username = 'StarSeeker'), 5, 'Początek przygody', 'Drużyna Pierścienia to wzorzec fantasy. Każda minuta zachwyca.'),

-- TechWizard (filmy 2, 5, 8) – drugi głos przy filmach 2, 5, 8
(2, (SELECT id FROM Account WHERE username = 'TechWizard'), 5, 'Cyfrowa rewolucja', 'Matrix to fundament cyberpunku. Wachowscy wyprzedzili epokę.'),
(5, (SELECT id FROM Account WHERE username = 'TechWizard'), 3, 'Cyfrowy pojedynek', 'Finałowa walka Neo vs Smith w deszczu kodu to sztuka.'),
(8, (SELECT id FROM Account WHERE username = 'TechWizard'), 5, 'Tarantino rządzi', 'Dialogi Vincenta i Julesa są cytatami na zawsze. A taniec? Bezcenne.'),

-- ====== Uzupełnienie: brakujące drugie recenzje dla filmów 3,6,9,10,11,12,13,14,15 ======
-- Film 3 (był PixelQueen) -> dodaje NightOwl
(3, (SELECT id FROM Account WHERE username = 'NightOwl'), 5, 'Klasyk gangsterski', 'Ojciec Chrzestny to kwintesencja kina. Nie można przejść obok niego obojętnie.'),
-- Film 6 (był ShadowCoder) -> dodaje WaveRider
(6, (SELECT id FROM Account WHERE username = 'WaveRider'), 5, 'Mrok Gotham', 'Mroczny Rycerz uderza z siłą. To coś więcej niż komiks.'),
-- Film 9 (był RetroGamer) -> dodaje StarSeeker
(9, (SELECT id FROM Account WHERE username = 'StarSeeker'), 3, 'Król w cieniu', 'Trudno oceniać przed premierą, ale mam nadzieję na godny biopic.'),
-- Film 10 (był WaveRider) -> dodaje PixelQueen
(10, (SELECT id FROM Account WHERE username = 'PixelQueen'), 4, 'Koniec cyrku', 'Finał Digital Circus zaskoczył mnie emocjonalnie. Warto było czekać.'),
-- Film 11 (był ShadowCoder) -> dodaje NightOwl (drugi raz)
(11, (SELECT id FROM Account WHERE username = 'NightOwl'), 4, 'Poza czasem', 'Interstellar z każdym seansem nabiera głębi. Muzyka i obraz są zachwycające.'),
-- Film 12 (był NightOwl) -> dodaje RetroGamer
(12, (SELECT id FROM Account WHERE username = 'RetroGamer'), 5, 'Skazani na doskonałość', 'Shawshank to film, który daje siłę. Finał to czyste katharsis.'),
-- Film 13 (był PixelQueen) -> dodaje TechWizard
(13, (SELECT id FROM Account WHERE username = 'TechWizard'), 4, 'Wojna o Śródziemie', 'Dwie Wieże to epicka bitwa i świetny rozwój wątku Golluma.'),
-- Film 14 (był RetroGamer) -> dodaje ShadowCoder
(14, (SELECT id FROM Account WHERE username = 'ShadowCoder'), 5, 'Idealny dreszczowiec', 'Parasite to precyzyjny mechanizm. Każdy detal ma znaczenie.'),
-- Film 15 (był WaveRider) -> dodaje StarSeeker
(15, (SELECT id FROM Account WHERE username = 'StarSeeker'), 4, 'Jazzowa burza', 'Whiplash to koncert napięcia. Ostatnie minuty są niesamowite.');

